const fs = require('fs');
const path = require('path');
const out = [];
for (const item of items) {
  const j = item.json || {};
  const body = j.body || {};
  try {
    const relPath = body.path;
    const b64 = body.content_b64;
    if (!relPath || typeof b64 !== 'string') { out.push({json:{ok:false,error:'missing path or content_b64'}}); continue; }
    const root = path.resolve('/host-repo');
    const target = path.resolve(root, relPath);
    if (target !== root && !target.startsWith(root + path.sep)) { out.push({json:{ok:false,error:'path escapes repo root'}}); continue; }
    fs.mkdirSync(path.dirname(target), {recursive:true});
    const buf = Buffer.from(b64, 'base64');
    fs.writeFileSync(target, buf);
    out.push({json:{ok:true,path:relPath,bytes:buf.length}});
  } catch (e) {
    out.push({json:{ok:false,error:String(e && e.message || e)}});
  }
}
return out;
